# 기준선 항등식: E_{a~π}[∇log π(a|s) · b(s)] = 0 — 그리고 분산은?
import numpy as np
def softmax(z): e = np.exp(z - z.max()); return e / e.sum()
U = np.array([1.0, 3.0]); p = softmax(np.zeros(2))
score = [np.eye(2)[a] - p for a in range(2)]       # ∇log π(a)
for b in [0.0, 1.0, 2.0, 5.0]:
    g = [score[a] * (U[a] - b) for a in range(2)]  # 표본 하나짜리 추정치(행동별)
    mean = sum(p[a] * g[a] for a in range(2))
    var = sum(p[a] * np.sum((g[a] - mean) ** 2) for a in range(2))
    print(f"b={b}: mean {np.round(mean, 3)}  var {var:.3f}  E[score*b] {np.round(sum(p[a]*score[a]*b for a in range(2)), 3)}")
